      #[cfg(target_os = "linux")]
      fn write_if_changed(path: std::path::PathBuf, bytes: &[u8]) {
          use std::fs;
          if fs::read(&path)
              .map(|existing| existing == bytes)
              .unwrap_or(false)
          {
              return;
          }
          if let Some(parent) = path.parent() {
              let _ = fs::create_dir_all(parent);
          }
          let _ = fs::write(path, bytes);
      }

