          let mut layout = use_context::<Signal<ui::UiLayout>>();

          let db = use_context::<DbHandle>();
          let items_res = use_context::<Resource<Vec<CalendarItem>>>();

          let cal_res = use_context::<Resource<Vec<Calendar>>>();
