              .get_string(&path)
              .map(|s| s.to_string_lossy().into_owned())
              .unwrap_or_default();
          let cpath = cstring(path);
          let db = unsafe { kal_ffi::kal_open(cpath.as_ptr()) };
          if db.is_null() {
