/* Kal base stylesheet.
 *
 * Theming contract: BOTH palettes are static blocks here. Light on :root,
 * dark on [data-theme="dark"] — the .app root div carries the data-theme
 * attribute (set from UiLayout.theme in main.rs), so descendants resolve
 * dark vars while body keeps the light fallback.
 */

:root {
    --select-chevron: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%236a737d' stroke-width='1.5' fill='none'/%3E%3C/svg%3E");
    --bg: #ffffff;
    --bg-alt: #f5f6f8;
    --fg: #1b1f24;
    --fg-muted: #6a737d;
    --accent: #3366cc;
    --accent-soft: #e8effc;
    --border: #d8dee4;
    --today: #eef4ff;
}

[data-theme="dark"] {
    --select-chevron: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%239aa4ae' stroke-width='1.5' fill='none'/%3E%3C/svg%3E");
    --bg: #16191d;
    --bg-alt: #1f2329;
    --fg: #e6e8eb;
    --fg-muted: #9aa4ae;
    --accent: #6c99f0;
    --accent-soft: #24304a;
    --border: #33393f;
    --today: #22304a;
}

/* Opaque surfaces so nothing depends on <body>'s (always-light) paint. */
.app { background: var(--bg); color: var(--fg); }

/* Semi-transparent scrim behind the mobile overlay drawer. Tapping it
   closes the drawer. Rendered only when a mobile drawer is open. */
.drawer-scrim {
    position: fixed;
    inset: 0;
    top: 48px; /* starts below the topbar */
    background: rgba(0, 0, 0, 0.42);
    z-index: 40;
}

/* Mobile overlay drawer: slides above the calendar rather than pushing it
   aside (Google Calendar style). Desktop keeps the in-flow push sidebar. */
.app.mobile .sidebar {
    position: fixed;
    top: 0;
    bottom: 0;
    left: 0;
    z-index: 50;
    border-right: 1px solid var(--border);
    box-shadow: 4px 0 24px rgba(0, 0, 0, 0.28);
    transition: transform 0.22s ease, visibility 0.22s;
    overflow-y: auto;
}
.app.mobile .sidebar .resize-handle { display: none; }

.month-grid, .day-scroll, .day-canvas, .agenda-list, .day-list {
    background: var(--bg);
}

* { box-sizing: border-box; }

html, body, #main { margin: 0; height: 100%; }

body {
    font-family: system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--fg);
    overflow: hidden;
}

.app {
    display: flex;
    flex-direction: column;
    height: 100vh;
    width: 100vw;
    background: var(--bg);
    color: var(--fg);
}
.app.resizing { cursor: col-resize; user-select: none; }
.app.resizing .sidebar { transition: none; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
@media (prefers-reduced-motion: reduce) {
    * { transition: none !important; animation: none !important; }
}

/* ---- controls ---- */

button, select, input[type="text"], input[type="date"], input[type="time"] {
    background: var(--bg);
    color: var(--fg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 13px;
    line-height: 1.4;
}
button { cursor: pointer; transition: background 0.12s ease, border-color 0.12s ease; }
button:hover { border-color: var(--accent); background: var(--accent-soft); }
button.primary {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
    font-weight: 500;
}
button.primary:hover { filter: brightness(1.08); }
button.danger:hover { border-color: #c0392b; color: #c0392b; }

.icon-btn {
    background: transparent;
    border: none;
    border-radius: 8px;
    min-width: 32px;
    height: 30px;
    font-size: 15px;
    line-height: 1;
    padding: 0 6px;
    color: var(--fg);
}
.icon-btn:hover { background: var(--accent-soft); border-color: transparent; }
.icon-btn.hamburger { font-size: 16px; }

select {
    appearance: none;
    -webkit-appearance: none;
    padding-right: 30px;
    background-image: var(--select-chevron);
    background-repeat: no-repeat;
    background-position: right 10px center;
}

input[type="checkbox"] { accent-color: var(--accent); cursor: pointer; }

/* ---- layout ---- */

.topbar {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 48px;
    padding: 6px 14px;
    border-bottom: 1px solid var(--border);
    background: var(--bg-alt);
}
.topbar h1 { font-size: 17px; font-weight: 600; margin: 0; }
.topbar .spacer { flex: 1; }
.subtitle { color: var(--fg-muted); font-size: 12px; }
.tb-controls { display: flex; gap: 8px; align-items: center; }
.prefs-toggle { display: none; font-size: 16px; }

.prefs-drawer {
    position: fixed;
    top: 56px;
    right: 10px;
    z-index: 60;
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 12px;
    min-width: 220px;
    background: var(--bg-alt);
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.22);
}
.prefs-drawer select, .prefs-drawer button { width: 100%; }

.body { display: flex; flex: 1; min-height: 0; }

.sidebar {
    position: relative;
    width: 230px;
    padding: 14px 12px;
    border-right: 1px solid var(--border);
    background: var(--bg-alt);
    overflow-x: hidden;
    white-space: nowrap;
    transition: width 0.15s ease;
}
.sidebar h2 {
    font-size: 11px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--fg-muted);
    margin: 18px 2px 6px;
}
.sidebar ul { list-style: none; padding: 0; margin: 0; }
.sidebar li {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 4px 2px;
    font-size: 13px;
}
.dot { width: 10px; height: 10px; border-radius: 50%; flex: none; }
.sidebar button { width: 100%; text-align: left; }

.sidebar .resize-handle {
    position: absolute;
    top: 0; right: -3px;
    width: 6px; height: 100%;
    cursor: col-resize;
    z-index: 10;
}
.sidebar .resize-handle:hover { background: var(--accent); opacity: 0.45; }

.content { flex: 1; display: flex; flex-direction: column; min-width: 0; }

/* ---- navigation strip ---- */

.month-nav {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 10px 14px;
}
.month-nav h2 { font-size: 16px; margin: 0 10px 0 6px; }

/* ---- month grid ---- */

.month-grid { display: flex; flex-direction: column; flex: 1; min-height: 0; padding: 0 8px 8px; }
.month-head, .month-row { display: grid; grid-template-columns: repeat(7, 1fr); }
.month-head div {
    padding: 4px;
    font-size: 11px;
    font-weight: 600;
    color: var(--fg-muted);
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.month-row { flex: 1; border-top: 1px solid var(--border); min-height: 64px; }
.month-cell {
    border-right: 1px solid var(--border);
    padding: 3px 5px;
    overflow: hidden;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    gap: 2px;
}
.month-cell:last-child { border-right: none; }
.month-cell:hover { background: var(--bg-alt); }
.month-cell.other { color: var(--fg-muted); opacity: 0.55; }
.month-cell.today { background: var(--today); }
.day-num { font-size: 12px; align-self: flex-end; }
.event-chip {
    font-size: 11px;
    padding: 2px 6px;
    border-radius: 5px;
    color: #fff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ---- lists (day / week / agenda) ---- */

.day-list, .agenda-list {
    list-style: none;
    margin: 0;
    padding: 8px 12px;
    overflow-y: auto;
    flex: 1;
}
.day-list li, .agenda-list li {
    display: flex;
    gap: 10px;
    align-items: baseline;
    padding: 7px 10px;
    border-bottom: 1px solid var(--border);
    border-radius: 6px;
    cursor: pointer;
    font-size: 13px;
}
.day-list li:hover, .agenda-list li:hover { background: var(--bg-alt); }
.when { color: var(--fg-muted); font-size: 12px; min-width: 110px; }
.agenda-date { min-width: 90px; color: var(--accent); font-size: 12px; font-weight: 600; }
.empty { color: var(--fg-muted); padding: 24px; text-align: center; justify-content: center; }
.task-check { flex: none; }
.item-dot { flex: none; align-self: center; width: 8px; height: 8px; border-radius: 50%; }
img.profile-avatar, .profile-avatar-initials {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    object-fit: cover;
    flex: none;
}
.profile-avatar-initials {
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--accent);
    color: #fff;
    font-weight: 600;
    font-size: 15px;
}
button.profile-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 8px;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 13px;
}
button.profile-header:hover { background: var(--accent-soft); border-radius: 8px; }
.profile-name { font-weight: 600; color: var(--fg); }
button.file-upload {
    position: relative;
    display: inline-flex;
    align-items: center;
    overflow: hidden;
    cursor: pointer;
    font-size: 12px;
    padding: 2px 8px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: var(--bg-alt);
    color: var(--fg);
}
button.file-upload:hover { border-color: var(--accent); }
button.file-upload input[type="file"] {
    /* Cover the whole button so a tap/click lands directly on the file
       input; the picker opens even where label->input forwarding is
       unreliable (Android WebView). */
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    cursor: pointer;
    border: none;
    background: transparent;
}

/* ---- editor modal ---- */

.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100;
}
.modal {
    background: var(--bg);
    color: var(--fg);
