librarian.handleSteps:
function* ({ prompt, params, logger }) {
    const repoUrl = params?.repoUrl;
    if (!repoUrl) {
      yield {
        toolName: "set_output",
        input: {
          message: "Error: repoUrl is required. Provide a GitHub repository URL in params."
        }
      };
      return;
    }
    const timestamp = Date.now(), cloneDir = "/tmp/librarian-" + (String(repoUrl).split("/").pop()?.replace(/\.git$/, "") || "repo") + "-" + timestamp;
    logger.info("Cloning " + repoUrl + " into " + cloneDir);
    const { toolResult } = yield {
      toolName: "run_terminal_command",
      input: {
        command: "git clone --depth 1 '" + repoUrl + "' '" + cloneDir + "'",
        timeout_seconds: 180
      }
    }, result = toolResult?.[0];
    if (result && result.type === "json") {
      const value = result.value;
      if ((typeof value?.exitCode === "number" ? value.exitCode : void 0) !== 0) {
        const stderr = typeof value?.stderr === "string" ? value.stderr : "Unknown error";
        logger.error("Clone failed: " + stderr);
        yield {
          toolName: "set_output",
          input: {
            message: "Failed to clone repository: " + stderr
          }
        };
        return;
      }
    }
    logger.info("Clone complete. Exploring repo...");
    yield {
      toolName: "add_message",
      input: {
        role: "user",
        content: "The repository has been cloned to `" + cloneDir + `\`. Use run_terminal_command with shell commands (ls, cat, find, grep, head, tree) to explore it. Do NOT use read_files, list_directory, glob, or code_search \u2014 they cannot access /tmp paths. Do NOT copy files into the project directory.

Now answer this question about the repo:

` + (prompt || "Provide an overview of this repository.") + `

When done, call set_output with your answer, relevantFiles (absolute paths), and cloneDir: "` + cloneDir + '".'
      },
      includeToolCall: !1
    };
    yield "STEP_ALL";
  }

