/// Resolve `com.kal.calendar.KalFilePicker` through the activity's class
/// loader. `JNIEnv::find_class` on a thread attached from native code uses
/// the *system* class loader, which cannot see application classes — the
/// lookup throws ClassNotFoundException and (left pending) crashes the app on
/// thread detach. Getting the class via `Class.getClassLoader().loadClass()`
/// uses the app's real loader and works from any attached thread.
fn find_kal_file_picker(env: &mut jni::JNIEnv, activity: &jni::objects::JObject) -> jni::errors::Result<jni::objects::JClass> {
    use jni::objects::{JValue, JString};
    // java/lang/Class is a framework class; GetObjectClass needs no lookup.
    let activity_cls = env.get_object_class(activity)?;
    let loader = env
        .call_method(&activity_cls, "getClassLoader", "()Ljava/lang/ClassLoader;", &[])?
        .l()?;
    let name = env.new_string("com/kal/calendar/KalFilePicker")?;
    let cls = env.call_method(
        &loader,
        "loadClass",
        "(Ljava/lang/String;)Ljava/lang/Class;",
        &[JValue::Object(&name)],
    )?.l()?;
    Ok(cls.into())
}
```

