/// Start a daemon thread that periodically runs sync rounds while this device
/// is paired, so same-phrase devices converge automatically (the user no
/// longer has to press "Sync now" while both apps happen to be online).
/// Idempotent: only one driver thread is ever started per process.
pub fn start_background_sync() {
