/* Kal base stylesheet.
 *
 * Theming contract: BOTH palettes are static blocks here. Light on :root,
 * dark on [data-theme="dark"] — the .app root div carries the data-theme
 * attribute (set from UiLayout.theme in main.rs), so descendants resolve
 * dark vars while body keeps the light fallback.
 */

:root {
    --select-chevron: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%236a737d' stroke-width='1.5' fill='none'/%3E%3C/svg%3E");
    --bg: #ffffff;
    --bg-alt: #f5f6f8;
    --fg: #1b1f24;
    --fg-muted: #6a737d;
    --accent: #3366cc;
    --accent-soft: #e8effc;
    --border: #d8dee4;
    --today: #eef4ff;
}

[data-theme="dark"] {
    --select-chevron: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%239aa4ae' stroke-width='1.5' fill='none'/%3E%3C/svg%3E");
    --bg: #16191d;
    --bg-alt: #1f2329;
    --fg: #e6e8eb;
    --fg-muted: #9aa4ae;
    --accent: #6c99f0;
    --accent-soft: #24304a;
    --border: #33393f;
    --today: #22304a;
}

/* Opaque surfaces so nothing depends on <body>'s (always-light) paint. */
.app { background: var(--bg); color: var(--fg); }

/* Semi-transparent scrim behind the mobile overlay drawer. Tapping it
   closes the drawer. Rendered only when a mobile drawer is open. */
.drawer-scrim {
    position: fixed;
    inset: 0;
    top: 48px; /* starts below the topbar */
    background: rgba(0, 0, 0, 0.42);
    z-index: 40;
}

/* Mobile overlay drawer: slides above the calendar rather than pushing it
   aside (Google Calendar style). Desktop keeps the in-flow push sidebar. */
.app.mobile .sidebar {
    position: fixed;
    top: 0;
    bottom: 0;
    left: 0;
    z-index: 50;
    border-right: 1px solid var(--border);
    box-shadow: 4px 0 24px rgba(0, 0, 0, 0.28);
    transition: transform 0.22s ease, visibility 0.22s;
    overflow-y: auto;
}
.app.mobile .sidebar .resize-handle { display: none; }

.month-grid, .day-scroll, .day-canvas, .agenda-list, .day-list {
    background: var(--bg);
}

* { box-sizing: border-box; }

html, body, #main { margin: 0; height: 100%; }

body {
    font-family: system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--fg);
    overflow: hidden;
}

.app {
    display: flex;
    flex-direction: column;
    height: 100vh;
    width: 100vw;
    background: var(--bg);
    color: var(--fg);
}
.app.resizing { cursor: col-resize; user-select: none; }
.app.resizing .sidebar { transition: none; }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
@media (prefers-reduced-motion: reduce) {
    * { transition: none !important; animation: none !important; }
}

/* ---- controls ---- */

button, select, input[type="text"], input[type="date"], input[type="time"] {
    background: var(--bg);
    color: var(--fg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 13px;
    line-height: 1.4;
}
button { cursor: pointer; transition: background 0.12s ease, border-color 0.12s ease; }
button:hover { border-color: var(--accent); background: var(--accent-soft); }
button.primary {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
    font-weight: 500;
}
button.primary:hover { filter: brightness(1.08); }
button.danger:hover { border-color: #c0392b; color: #c0392b; }

.icon-btn {
    background: transparent;
    border: none;
    border-radius: 8px;
