use std::thread;
use std::time::{Duration, Instant};

use kal_sync::live::IrohTransport;
use kal_sync::{ChainIdentity, Transport as _};

const PHRASE: &str = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_max_level(tracing::Level::DEBUG)
        .with_ansi(false)
        .with_target(true)
        .try_init()
        .ok();

    let identity = ChainIdentity::from_phrase(PHRASE)?;
    println!("chain fingerprint: {}", identity.fingerprint().fingerprint_hex);

    let a_id = ulid::Ulid::new();
    let b_id = ulid::Ulid::new();

    // Connect on dedicated threads (connect uses block_on internally).
    let a = thread::spawn(move || IrohTransport::connect(&identity, a_id, IrohTransport::new_node_secret()));
    let b = thread::spawn(|| IrohTransport::connect(&identity, b_id, IrohTransport::new_node_secret()));

    let a = a.join().unwrap()?;
    let b = b.join().unwrap()?;
    println!("A endpoint: {}", a.endpoint_id());
    println!("B endpoint: {}", b.endpoint_id());

    let deadline = Instant::now() + Duration::from_secs(180);
    let mut last_report = Instant::now();
    loop {
        let aj = a.is_joined();
        let bj = b.is_joined();
        if last_report.elapsed() >= Duration::from_secs(5) {
            println!("[t={:.0}s] A joined={aj} B joined={bj}", deadline.elapsed().as_secs_f64());
            last_report = Instant::now();
        }
        if aj && bj { break; }
        if Instant::now() >= deadline {
            println!("TIMEOUT: never joined (A={aj}, B={bj})");
            std::process::exit(1);
        }
        thread::sleep(Duration::from_millis(500));
    }
    println!("both joined! exchanging state...");
    a.send("", b"hello-from-A")?;
    let t0 = Instant::now();
    loop {
        if let Some((from, bytes)) = b.recv() {
            println!("B received {:?} from {}", String::from_utf8_lossy(&bytes), from);
            break;
        }
        if t0.elapsed() > Duration::from_secs(30) {
            println!("TIMEOUT: B never received A's broadcast");
            std::process::exit(1);
        }
        thread::sleep(Duration::from_millis(200));
    }
    println!("PROBE OK");
    Ok(())
}
```

